import type { Project } from './types'
import generated from './projects.generated.json'

// Projects are the single source of truth. They are generated by
// `node scripts/sync-projects.mjs` from the repo registry + `project.yml`
// manifests (see scripts/sync-projects.mjs and README). Do not edit this
// file's data by hand — edit registry.yml or the project manifests instead.
export type { Project, ProjectStatus, ProjectLink, ProjectCategory } from './types'

// Display order: these slugs come first (the home page shows the first three),
// everything else keeps the generated order.
const PINNED = [
  'browserzap',
  'mrrdue',
  'aisearchaudit',
  'unitconverterone',
  'tryfreecalculator',
  'consentvalidator',
  'izmo',
  'imageconverter',
  'makeupnnow',
  'faqflow',
]

const rank = (slug: string) => {
  const i = PINNED.indexOf(slug)
  return i === -1 ? PINNED.length : i
}

/** Every project, including explorations (used for the detail pages). */
export const allProjects: Project[] = (generated as Project[])
  .map((p, i) => ({ p, i }))
  .sort((a, b) => rank(a.p.slug) - rank(b.p.slug) || a.i - b.i)
  .map(({ p }) => p)


/** Main portfolio projects (home page and the Work grid). */
export const projects: Project[] = allProjects.filter((p) => !p.explored)

/** Early, paused or retired projects, shown in a compact "Explorations" list. */
export const explorations: Project[] = allProjects.filter((p) => p.explored)
